
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { ArrowLeft, Location, Van, CircleCheck, Box, Check, Close } from '@element-plus/icons-vue'
import { adminOrderApi, riderApi } from '@/api'
import type { OrderDetail, Rider } from '@/types'
import { dateTime, money, orderStatusType } from '@/utils'
const route=useRoute();const router=useRouter();const order=ref<OrderDetail>();const riders=ref<Rider[]>([]);const dispatchDialog=ref(false);const dispatch=reactive({riderId:undefined as number|undefined,adminRemark:'已安排骑手配送'});
const load=async()=>{order.value=await adminOrderApi.detail(Number(route.params.id));riders.value=await riderApi.available()};onMounted(load)
const action=async(type:string)=>{if(!order.value)return;if(type==='dispatch'){dispatch.riderId=undefined;dispatchDialog.value=true;return}if(type==='cancel'){const {value}=await ElMessageBox.prompt('请输入取消原因','取消订单',{type:'warning',inputValidator:v=>v?true:'请输入取消原因'});await adminOrderApi.cancel(order.value.id,value)}else{const text:any={accept:'确认接单并开始备货？',pack:'确认打包完成？',complete:'确认送达？'};await ElMessageBox.confirm(text[type],'订单操作',{type:'warning'});if(type==='accept')await adminOrderApi.accept(order.value.id,'已接单，开始备货');if(type==='pack')await adminOrderApi.pack(order.value.id,'药品已打包完成');if(type==='complete')await adminOrderApi.complete(order.value.id,'已确认送达')}ElMessage.success('操作成功');await load()}
const submitDispatch=async()=>{if(!order.value||!dispatch.riderId)return ElMessage.warning('请选择骑手');await adminOrderApi.dispatch(order.value.id,dispatch);ElMessage.success('派单成功');dispatchDialog.value=false;await load()}
</script>
<template><div v-if="order"><button class="back-btn" @click="router.back()"><el-icon><ArrowLeft/></el-icon>返回订单管理</button><div class="admin-page-head"><div><span class="eyebrow">ORDER DETAIL</span><h1>订单 {{order.orderNo}}</h1><p>下单时间：{{dateTime(order.createTime)}}　用户：{{order.username||'-'}}</p></div><el-tag :type="orderStatusType(order.orderStatus)" size="large" round>{{order.orderStatusName}}</el-tag></div><section class="admin-order-hero"><div><span>订单金额</span><b>{{money(order.orderAmount)}}</b></div><div><span>当前状态</span><b>{{order.orderStatusName}}</b></div><div><span>配送骑手</span><b>{{order.riderName||'待派单'}}</b></div><div class="hero-actions"><el-button v-if="order.orderStatus==='PENDING_ACCEPT'" type="primary" :icon="Check" @click="action('accept')">确认接单</el-button><el-button v-if="order.orderStatus==='TO_PACK'" type="warning" :icon="Box" @click="action('pack')">完成打包</el-button><el-button v-if="order.orderStatus==='TO_DISPATCH'" type="primary" :icon="Van" @click="action('dispatch')">派单配送</el-button><el-button v-if="order.orderStatus==='DELIVERING'" type="success" :icon="CircleCheck" @click="action('complete')">确认送达</el-button><el-button v-if="['PENDING_ACCEPT','TO_PACK','TO_DISPATCH'].includes(order.orderStatus)" plain type="danger" :icon="Close" @click="action('cancel')">取消订单</el-button></div></section><div class="detail-layout"><main><section class="detail-block"><h2><el-icon><Location/></el-icon>收货信息</h2><p><b>{{order.receiverName}} {{order.receiverPhone}}</b></p><p>{{order.receiverAddress}}</p><p v-if="order.userRemark" class="remark">用户备注：{{order.userRemark}}</p><p v-if="order.adminRemark" class="remark">管理员备注：{{order.adminRemark}}</p></section><section class="detail-block"><h2>商品明细</h2><article v-for="item in order.items" :key="item.id" class="item-line"><div class="item-img"><img v-if="item.medicineImage" :src="item.medicineImage"/><span v-else>药</span></div><div><b>{{item.medicineName}}</b><span>{{money(item.medicinePrice)}} × {{item.quantity}}</span></div><strong>{{money(item.subtotalAmount)}}</strong></article></section></main><aside><section class="detail-block timeline"><h2>状态日志</h2><el-timeline><el-timeline-item v-for="log in order.statusLogs" :key="log.id" :timestamp="dateTime(log.createTime)" :type="log.afterStatus==='CANCELED'?'danger':log.afterStatus==='COMPLETED'?'success':'primary'"><b>{{log.afterStatusName}}</b><p v-if="log.remark">{{log.remark}}</p></el-timeline-item></el-timeline></section><section v-if="order.riderName" class="detail-block rider"><h2><el-icon><Van/></el-icon>骑手信息</h2><div class="rider-icon">骑</div><b>{{order.riderName}}</b><p>{{order.riderPhone}}</p></section></aside></div><el-dialog v-model="dispatchDialog" title="派单并开始配送" width="min(460px,92%)"><el-form label-position="top"><el-form-item label="配送骑手" required><el-select v-model="dispatch.riderId" placeholder="请选择可接单骑手" style="width:100%"><el-option v-for="r in riders" :key="r.id" :label="`${r.riderName} · ${r.phone}`" :value="r.id"/></el-select></el-form-item><el-form-item label="管理员备注"><el-input v-model="dispatch.adminRemark" maxlength="255"/></el-form-item></el-form><template #footer><el-button @click="dispatchDialog=false">取消</el-button><el-button type="primary" @click="submitDispatch">确认派单</el-button></template></el-dialog></div></template>
<style scoped>.back-btn{border:0;background:transparent;color:#60768e;padding:0;margin-bottom:16px;cursor:pointer;display:flex;gap:5px;align-items:center}.eyebrow{font-size:11px;color:#1677ff;letter-spacing:2px;font-weight:700}.admin-page-head h1{font-size:24px;margin:6px 0}.admin-page-head p{margin:0;color:#8491a4;font-size:12px}.admin-order-hero{background:linear-gradient(135deg,#0b4f9c,#1677ff);color:#fff;border-radius:16px;padding:21px 26px;display:grid;grid-template-columns:repeat(3,1fr) auto;gap:20px;align-items:center}.admin-order-hero span,.admin-order-hero b{display:block}.admin-order-hero span{font-size:11px;color:#cce9ff}.admin-order-hero b{font-size:20px;margin-top:5px}.hero-actions{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}.detail-layout{display:grid;grid-template-columns:1fr 340px;gap:18px;margin-top:18px}.detail-block{background:#fff;border:1px solid #e6edf7;border-radius:14px;padding:19px;margin-bottom:16px}.detail-block h2{font-size:15px;margin:0 0 13px;display:flex;gap:6px;align-items:center}.detail-block h2 .el-icon{color:#1677ff}.detail-block p{font-size:13px;color:#728198;line-height:1.7;margin:4px 0}.remark{background:#f7faff;padding:8px;border-radius:8px;font-size:12px!important}.item-line{display:flex;align-items:center;gap:12px;border-bottom:1px solid #f0f3f7;padding:10px 0}.item-line:last-child{border:0}.item-img{width:45px;height:45px;border-radius:11px;background:#eaf5ff;overflow:hidden;display:grid;place-items:center;color:#1677ff}.item-img img{width:100%;height:100%;object-fit:cover}.item-line>div:nth-child(2){flex:1}.item-line b,.item-line span{display:block}.item-line b{font-size:13px}.item-line span{font-size:11px;color:#8b98aa;margin-top:5px}.item-line strong{font-size:14px}.timeline :deep(.el-timeline-item__timestamp){font-size:10px}.timeline :deep(.el-timeline-item__content){font-size:13px}.timeline p{font-size:12px;margin:4px 0}.rider{text-align:center}.rider h2{text-align:left}.rider-icon{width:50px;height:50px;border-radius:16px;background:linear-gradient(135deg,#19b98a,#68d8bf);color:#fff;display:grid;place-items:center;margin:0 auto 9px;font-size:19px}.rider p{font-size:12px}@media(max-width:850px){.admin-order-hero{grid-template-columns:repeat(2,1fr)}.detail-layout{grid-template-columns:1fr}.detail-layout aside{display:contents}.timeline{order:3}.rider{order:4}}@media(max-width:550px){.admin-order-hero{grid-template-columns:1fr}.hero-actions{justify-content:flex-start}}</style>
